function renderDetailSections(hero) {
  const detail = hero.details;
  if (!detail) return "";

  const awakenings = (detail.awakening || [])
    .map((item) => `
      <div class="detail-awakening-row">
        <div class="detail-awakening-level">${esc(item.level)}</div>
        <div class="detail-awakening-copy">
          <p>${esc(item.text)}</p>
        </div>
      </div>
    `)
    .join("");

  const stats = (detail.statPriority || [])
    .map((item) => `<li>${esc(item)}</li>`)
    .join("");


  const gear = detail.gear
    ? `
      <section class="detail-section detail-guide-section">
        <div class="detail-section-head">
          <p class="section-kicker">GEAR</p>
          <h2>추천 장비</h2>
        </div>
        <div class="detail-artifact-box">
          <div>
            <span>${esc(detail.gear.label || "추천 장비")}</span>
            <strong>${esc(detail.gear.name || "")}</strong>
          </div>
          <p>${esc(detail.gear.text || "")}</p>
        </div>
        <p class="detail-gear-caution"><span aria-hidden="true">※</span> 모든 추천 장비는 범용적인 운용 기준을 바탕으로 한 참고용 세팅입니다. 각성 단계, 보유 장비 옵션, 던전 및 콘텐츠 기믹에 따라 최적 장비는 달라질 수 있습니다.</p>
      </section>
    `
    : "";


  const roleBuild = (detail.roleSummary || stats || detail.statNote)
    ? `
      <section class="detail-section detail-guide-section">
        <div class="detail-section-head">
          <p class="section-kicker">ROLE & BUILD</p>
          <h2>운용 · 장비 방향</h2>
        </div>
        ${detail.roleSummary ? `<p class="detail-guide-lead">${esc(detail.roleSummary)}</p>` : ""}
        ${stats ? `<ol class="detail-stat-list">${stats}</ol>` : ""}
        ${detail.statNote ? `<p class="detail-tip">TIP · ${esc(detail.statNote)}</p>` : ""}
      </section>
    `
    : "";

  const awakeningSection = awakenings
    ? `
      <section class="detail-section detail-guide-section">
        <div class="detail-section-head">
          <p class="section-kicker">AWAKENING</p>
          <h2>각성 A1~A5</h2>
        </div>
        <div class="detail-awakening-list">${awakenings}</div>
      </section>
    `
    : detail.awakeningUnavailable
      ? `
        <section class="detail-section detail-guide-section">
          <div class="detail-section-head">
            <p class="section-kicker">AWAKENING</p>
            <h2>각성 정보</h2>
          </div>
          <p class="detail-tip">${esc(detail.awakeningUnavailableText || "A1~A5 각성 정보가 제공되지 않습니다.")}</p>
        </section>
      `
      : "";


  return `
    ${detail.verifiedIntro ? `
      <section class="detail-highlight">
        <p class="section-kicker">VERIFIED INFO</p>
        <h2>${esc(hero.nameKr)} 상세 정보</h2>
        <p>${esc(detail.verifiedIntro)}</p>
      </section>
    ` : ""}
    ${gear}
    ${roleBuild}
    ${awakeningSection}
    ${(detail.note || detail.updated) ? `<p class="detail-source-note detail-source-standalone">${esc(detail.note || "")}${detail.updated ? ` · 확인 ${esc(detail.updated)}` : ""}</p>` : ""}
  `;
}

const HERO_QUICK_TRAIT_LABELS = {
  "단일 물리 공격": "단일 물리 딜러",
  "단일 마법 공격": "단일 마법 딜러",
  "광역 물리 공격": "광역 물리 딜러",
  "광역 마법 공격": "광역 마법 딜러",
  "단일 치유": "단일 힐러",
  "광역 치유": "광역 힐러",
  "매우 먼 사거리": "긴 사거리",
  "공중 유닛 공격 가능": "공중 대응",
  "듀얼 대상 공격": "2대상 공격",
  "생존": "생존력",
  "비용 회복": "코스트 회복"
};

function heroQuickSummary(hero) {
  const traits = Array.isArray(hero.traits) ? hero.traits : [];
  return traits.slice(0, 4).map((trait) => HERO_QUICK_TRAIT_LABELS[trait] || trait).join(" · ");
}

function heroDescription(hero) {
  const factions = hero.memberships.map((m) => m.kr).filter(Boolean).join(" · ");
  const contents = hero.contentTags.map((tag) => CONTENT_META[tag]?.kr).filter(Boolean).join(" · ");
  const contentText = contents ? ` 추천 콘텐츠: ${contents}.` : "";
  return `워처 오브 렐름 ${hero.nameKr}(${hero.nameEn}) 영웅 정보. ${hero.rarity} ${hero.class}, 소속 진영 ${factions}.${contentText} 한국명과 영문명을 나만겜 한국 영웅 위키에서 확인하세요.`;
}

// v2.14.9: Adapt canonical heroes.json fields at the rendering boundary.
// Keep the source data intact so subsequent gear/artifact updates remain compatible.
function normalizeHeroForDetail(hero) {
  const memberships = (Array.isArray(hero.memberships) ? hero.memberships : []).map((m) => ({
    ...m,
    kr: m.kr || m.factionKr || "",
    en: m.en || m.factionEn || ""
  }));
  const portrait = hero.portrait || memberships.find((m) => m.portrait)?.portrait || "";
  return {
    ...hero,
    memberships,
    // Root-relative paths also work on nested /hero/<id>/ routes and in OG metadata.
    portrait: portrait ? new URL(portrait, SITE + "/").pathname : "",
    contentTags: Array.isArray(hero.contentTags) ? hero.contentTags : []
  };
}

function renderHero(hero, env = {}) {
  hero = normalizeHeroForDetail(hero);
  const canonical = `${SITE}/hero/${encodeURIComponent(hero.id)}/`;
  const title = `나만겜 | ${hero.nameKr}(${hero.nameEn}) - 워처 오브 렐름 한국 영웅 위키`;
  const description = heroDescription(hero);
  const factions = hero.memberships.map((m) => m.kr).filter(Boolean);
  const contentNames = hero.contentTags.map((tag) => CONTENT_META[tag]?.kr).filter(Boolean);
  const image = hero.portrait ? `${SITE}${hero.portrait}` : `${SITE}/icon-512.png`;
  const particle = topicParticle(hero.nameKr);
  const isLord = hero.memberships.some((m) => m.lord);
  const collectionValueText = Number(hero.collectionValue || 0).toFixed(1);
  const quickSummary = heroQuickSummary(hero);

  const factionBadges = hero.memberships.map((m) =>
    `<span class="detail-faction-chip">${m.lord ? '<b>영주</b>' : ''}${esc(m.kr)}<small>${esc(m.en)}</small></span>`
  ).join("");

  const contentBadges = hero.contentTags.map((tag) => {
    const meta = CONTENT_META[tag];
    return meta ? `<span class="content-tag ${esc(tag)}">${esc(meta.kr)}</span>` : "";
  }).join("");

  const contentSection = contentNames.length
    ? `
      <section class="detail-section detail-content-section">
        <div class="detail-section-head">
          <p class="section-kicker">CONTENT</p>
          <h2>추천 콘텐츠</h2>
        </div>
        ${contentBadges ? `<div class="content-tags detail-content-tags">${contentBadges}</div>` : ""}
        <div class="detail-readable-copy"><p><strong>나만겜 추천 콘텐츠</strong> ${esc(contentNames.join(" · "))}</p></div>
      </section>
    `
    : "";

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    "name": title,
    "url": canonical,
    "description": description,
    "inLanguage": "ko-KR",
    "isPartOf": {
      "@type": "WebSite",
      "name": "나만겜 워처 오브 렐름 한국 영웅 위키",
      "url": `${SITE}/`
    },
    "mainEntity": {
      "@type": "Thing",
      "name": hero.nameKr,
      "alternateName": hero.nameEn,
      "description": `${hero.nameKr}(${hero.nameEn})는 워처 오브 렐름의 ${hero.rarity} ${hero.class} 영웅입니다.`,
      "image": image,
      "isPartOf": {
        "@type": "VideoGame",
        "name": "Watcher of Realms"
      }
    }
  };

  return `<!doctype html>
<html lang="ko">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="theme-color" content="#0b1018" />
  <title>${esc(title)}</title>
  <meta name="description" content="${esc(description)}" />
  <meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1" />
  <link rel="canonical" href="${canonical}" />
  <link rel="icon" type="image/png" sizes="64x64" href="/favicon-crystal-v1.png?v=2.11.43c" />
  <link rel="apple-touch-icon" href="/icon-192.png?v=2.11.43c" />
  <meta property="og:type" content="website" />
  <meta property="og:locale" content="ko_KR" />
  <meta property="og:site_name" content="나만겜 워처 오브 렐름 한국 영웅 위키" />
  <meta property="og:title" content="${esc(title)}" />
  <meta property="og:description" content="${esc(description)}" />
  <meta property="og:url" content="${canonical}" />
  <meta property="og:image" content="${esc(image)}" />
  <meta name="twitter:card" content="summary" />
  <meta name="twitter:title" content="${esc(title)}" />
  <meta name="twitter:description" content="${esc(description)}" />
  <meta name="twitter:image" content="${esc(image)}" />
  <link rel="stylesheet" href="/styles.css?v=2.13.4g" />
  <link rel="stylesheet" href="/comments.css?v=2.13.4k">
  <link rel="stylesheet" href="/collection-guide.css?v=2.14.13">
  <meta name="worwiki-detail-version" content="2.14.13">
  <script type="application/ld+json">${JSON.stringify(jsonLd).replaceAll("<", "\\u003c")}</script>
</head>
<body class="hero-detail-page">
  <header class="detail-topbar">
    <div class="wrap detail-topbar-inner">
      <a class="detail-brand" href="/">나만겜 <span>워처 오브 렐름 한국 영웅 위키</span></a>
      <div class="detail-topbar-actions">
        <a class="detail-gear-link" href="/gear-presets-v4"><span>장비 프리셋</span> <b>V4.0</b></a>
        <a class="detail-back" href="/">← 전체 도감</a>
      </div>
    </div>
  </header>

  <main class="wrap hero-detail-main">
    <nav class="detail-breadcrumb" aria-label="경로">
      <a href="/">영웅도감</a><span>›</span><strong>${esc(hero.nameKr)}</strong>
    </nav>

    <section class="hero-detail-card">
      <div class="hero-detail-visual">
        ${hero.portrait
          ? `<img src="${esc(hero.portrait)}" alt="${esc(hero.nameKr)} (${esc(hero.nameEn)}) 영웅 이미지" />`
          : `<div class="hero-detail-placeholder">${esc((hero.nameEn || hero.nameKr).charAt(0).toUpperCase())}</div>`}
      </div>

      <div class="hero-detail-copy">
        <p class="section-kicker">WATCHER OF REALMS · HERO</p>
        <h1>${esc(hero.nameKr)} <span>${esc(hero.nameEn)}</span></h1>
        <p class="hero-detail-summary">${esc(hero.nameKr)}의 영문명은 <strong>${esc(hero.nameEn)}</strong>입니다.</p>
        ${quickSummary ? `<p class="hero-quick-summary" aria-label="영웅 핵심 요약">${esc(quickSummary)}</p>` : ""}

        <div class="hero-detail-basic-tags">
          <span class="tag ${rarityClass(hero.rarity)}">${esc(hero.rarity)}</span>
          <span class="tag detail-class-tag">${esc(hero.class)}</span>
          ${wwReady(env) ? `<a id="hero-review-jump" class="hero-review-jump" href="#hero-comments" hidden><span aria-hidden="true">💬</span> 후기 <span id="hero-review-count">0</span></a>` : ""}
        </div>

        <dl class="hero-detail-facts${isLord ? "" : " no-lord"}">
          <div><dt>한국 이름</dt><dd>${esc(hero.nameKr)}</dd></div>
          <div><dt>영문 이름</dt><dd>${esc(hero.nameEn)}</dd></div>
          <div><dt>희귀도</dt><dd>${esc(hero.rarity)}</dd></div>
          <div><dt>직업</dt><dd>${esc(hero.class)}</dd></div>
          <div class="detail-collection-fact"><dt>수집가치</dt><dd><span class="collection-stars" aria-label="5점 만점에 ${collectionValueText}점">${collectionStars(hero.collectionValue)}</span><small>${collectionValueText} / 5.0</small><a class="collection-guide-jump" href="#collection-value-guide">평가 기준 보기</a></dd></div>
          ${isLord ? `<div><dt>영주 여부</dt><dd>영주</dd></div>` : ""}
        </dl>
      </div>
    </section>

    <section class="detail-section">
      <div class="detail-section-head">
        <p class="section-kicker">FACTION</p>
        <h2>소속 진영</h2>
      </div>
      <div class="detail-faction-list">${factionBadges}</div>
      <p class="detail-readable-copy">${esc(hero.nameKr)}${particle} ${esc(factions.join(" · "))} 소속의 ${esc(hero.rarity)} ${esc(hero.class)} 영웅입니다.</p>
    </section>

    ${contentSection}

    ${renderOfficialTraits(hero)}

    ${renderDetailSections(hero)}

    ${renderExclusiveArtifact(hero)}

    ${renderRelatedVideos(hero)}

    ${wwRenderSection(hero, env)}

    <nav class="hero-utility-links" aria-label="영웅 정보 보조 메뉴">
      <a href="/gear-presets-v4">장비 프리셋 보기 →</a>
      <a href="${REPORT_FORM}" target="_blank" rel="noopener noreferrer">정보 오류 제보 ↗</a>
    </nav>
    <div class="hero-return"><a href="/">← 영웅도감으로 돌아가기</a></div>
  </main>

  <footer class="detail-footer">
    <div class="wrap detail-footer-inner">
      <span>나만겜 제작 · 비공식 Watcher of Realms 팬사이트</span>
      <div class="detail-footer-links"><a href="${REPORT_FORM}" target="_blank" rel="noopener noreferrer">정보 제보 ↗</a><a href="${YOUTUBE}" target="_blank" rel="noopener noreferrer">나만겜 YouTube ↗</a></div>
    </div>
  </footer>
  ${wwReady(env) ? '<script src="/comments.js?v=2.13.4k" defer></script>' : ''}
</body>
</html>`;
}


