// Hero-specific editorial changes after the manual display-order baseline.
// Unix seconds only; keep the legacy site-wide news feed separate.
const WW_HERO_INFO_UPDATES = {};

async function wwRecentUpdates(env, heroes) {
  const heroActivity = Object.entries(WW_HERO_INFO_UPDATES)
    .filter(([id, time]) => heroes[id] && Number.isFinite(time) && time > 0)
    .map(([heroId, infoUpdatedAt]) => ({ heroId, infoUpdatedAt, reviewPublishedAt: 0 }));
  const items = WW_STATIC_UPDATES.map((item) => ({ ...item }));
  if (env.COMMENTS_DB) {
    try {
      const rows = await env.COMMENTS_DB.prepare(
        "SELECT id,hero_id,published_at FROM comments WHERE status='published' AND published_at IS NOT NULL ORDER BY published_at DESC,id DESC LIMIT 12"
      ).all();
      const latest = await env.COMMENTS_DB.prepare(
        "SELECT hero_id,MAX(published_at) AS published_at FROM comments WHERE status='published' AND published_at IS NOT NULL GROUP BY hero_id"
      ).all();
      for (const row of latest.results || []) {
        const publishedAt = Number(row.published_at);
        if (!heroes[row.hero_id] || !Number.isFinite(publishedAt) || publishedAt <= 0) continue;
        const activity = heroActivity.find((item) => item.heroId === row.hero_id);
        if (activity) activity.reviewPublishedAt = publishedAt;
        else heroActivity.push({ heroId: row.hero_id, infoUpdatedAt: 0, reviewPublishedAt: publishedAt });
      }
      for (const row of rows.results || []) {
        const hero = heroes[row.hero_id];
        const publishedAt = Number(row.published_at);
        if (!hero || !Number.isFinite(publishedAt)) continue;
        items.push({
          id: `review-${row.id}`,
          kind: "review",
          heroId: row.hero_id,
          heroName: hero.nameKr || row.hero_id,
          message: "새 유저 후기 등록",
          timestamp: publishedAt
        });
      }
    } catch (error) {
      console.error("Recent updates query failed:", error?.message || "unknown");
    }
  }
  items.sort((a, b) => (b.timestamp - a.timestamp) || String(b.id).localeCompare(String(a.id)));
  return new Response(JSON.stringify({ updates: items.slice(0, 3), heroActivity }), {
    status: 200,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      "x-content-type-options": "nosniff"
    }
  });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === "/api/recent-updates") {
      if (!["GET", "HEAD"].includes(request.method)) {
        return new Response(null, { status: 405, headers: { allow: "GET, HEAD" } });
      }
      const response = await wwRecentUpdates(env, HEROES);
      if (request.method === "HEAD") return new Response(null, { status: response.status, headers: response.headers });
      return response;
    }
    if (url.pathname === "/heroes.json") {
      if (!["GET", "HEAD"].includes(request.method)) return new Response(null, { status: 405, headers: { allow: "GET, HEAD" } });
      const site = request.headers.get("sec-fetch-site") || "";
      const dest = request.headers.get("sec-fetch-dest") || "";
      const referer = request.headers.get("referer") || "";
      const sameOriginFetch = (site === "same-origin" || referer.startsWith(`${SITE}/`)) && dest !== "document";
      if (!sameOriginFetch) {
        return new Response("직접 데이터 열람은 제공하지 않습니다.", { status: 403, headers: {
          "content-type": "text/plain; charset=UTF-8",
          "cache-control": "no-store",
          "x-robots-tag": "noindex, nofollow, noarchive",
          "cross-origin-resource-policy": "same-origin",
          "x-content-type-options": "nosniff"
        }});
      }
      const asset = await env.ASSETS.fetch(request);
      const headers = new Headers(asset.headers);
      headers.set("cache-control", "private, no-store");
      headers.set("x-robots-tag", "noindex, nofollow, noarchive");
      headers.set("cross-origin-resource-policy", "same-origin");
      headers.set("x-content-type-options", "nosniff");
      headers.set("vary", "Sec-Fetch-Site, Sec-Fetch-Dest, Referer");
      return new Response(request.method === "HEAD" ? null : asset.body, { status: asset.status, headers });
    }
    const commentsResponse = await wwHandle(request, env, ctx, HEROES);
    if (commentsResponse) return commentsResponse;
    const match = url.pathname.match(/^\/hero\/([^/]+)\/?$/);
    if (url.pathname === "/hero/site-update" || url.pathname === "/hero/site-update/") {
      return Response.redirect(`${SITE}/`, 302);
    }

    // HOME SAFETY ROUTE: the root must always render the hero wiki, never a sub-page.
    if (url.pathname === "/index.html") {
      return Response.redirect(`${SITE}/`, 301);
    }

    if (url.pathname === "/") {
      const body = request.method === "HEAD" ? null : wwProtectHtml(HOME_INDEX_HTML);
      return new Response(body, {
        status: 200,
        headers: wwProtectedPageHeaders({
          "content-type": "text/html; charset=UTF-8",
          "cache-control": "no-cache, max-age=0, must-revalidate",
          "x-robots-tag": "index, follow, noarchive",
          "x-worwiki-route": "home-direct-safe"
        })
      });
    }

    // Legacy nested gear URLs: redirect only. The actual pages are static flat assets.
    // This keeps the hero Worker isolated from gear-page rendering.
    if (url.pathname === "/gear-presets" || url.pathname === "/gear-presets/") {
      return Response.redirect(`${SITE}/gear-presets-v4`, 302);
    }
    const legacyGearMatch = url.pathname.match(/^\/gear-presets\/namangam(4\d{2})\/?$/);
    if (legacyGearMatch) {
      const n = Number(legacyGearMatch[1]);
      if (n >= 401 && n <= 424) return Response.redirect(`${SITE}/gear-preset-${n}`, 302);
    }

    if (["/growth-guide", "/growth-guide/", "/growth-guide/index.html"].includes(url.pathname)) {
      if (!["GET", "HEAD"].includes(request.method)) return new Response(null, {status:405, headers:{allow:"GET, HEAD"}});
      if (url.pathname !== "/growth-guide/") return Response.redirect(`${SITE}/growth-guide/`, 301);
      return new Response(request.method === "HEAD" ? null : wwProtectHtml(WW_GROWTH_GUIDE_HTML), {
        status:200, headers:wwProtectedPageHeaders({"content-type":"text/html; charset=UTF-8", "cache-control":"no-cache, max-age=0, must-revalidate", "x-robots-tag":"index, follow, noarchive", "x-worwiki-route":"growth-guide"})
      });
    }

    if (url.pathname === "/newbie" || url.pathname === "/newbie/") {
      if (url.pathname === "/newbie") {
        return Response.redirect(`${SITE}/newbie/`, 301);
      }
      const body = request.method === "HEAD" ? null : wwProtectHtml(renderNewbie());
      return new Response(body, {
        status: 200,
        headers: wwProtectedPageHeaders({
          "content-type": "text/html; charset=UTF-8",
          "cache-control": "no-cache, max-age=0, must-revalidate",
          "x-robots-tag": "index, follow, noarchive"
        })
      });
    }

    // Apply presentation updates to the deployed gear HTML without replacing its data.
    if (/^\/gear-preset-4(?:0[1-9]|1[0-9]|2[0-4])(?:\.html)?\/?$/.test(url.pathname) && ["GET", "HEAD"].includes(request.method)) {
      const asset = await env.ASSETS.fetch(request);
      if (request.method === "HEAD" || asset.status !== 200 || !(asset.headers.get("content-type") || "").includes("text/html")) return asset;
      let html = await asset.text();
      html = html.replace(/<div>\s*<dt>보조\s*속성<\/dt>/g, '<div class="gear-substat-row"><dt>보조 속성</dt>');
      html = html.replace('</head>', '<link rel="stylesheet" href="/gear-detail-readable.css?v=2.14.11"></head>');
      const headers = new Headers(asset.headers);
      headers.delete("content-length");
      headers.delete("content-encoding");
      headers.delete("etag");
      return new Response(html, {status: asset.status, headers});
    }

    if (!match) {
      return env.ASSETS.fetch(request);
    }

    const slug = decodeURIComponent(match[1]);
    const hero = HEROES[slug];

    if (!hero) {
      return new Response(renderNotFound(), {
        status: 404,
        headers: {
          "content-type": "text/html; charset=UTF-8",
          "cache-control": "public, max-age=60"
        }
      });
    }

    const canonicalPath = `/hero/${encodeURIComponent(hero.id)}/`;
    if (url.pathname !== canonicalPath) {
      return Response.redirect(`${SITE}${canonicalPath}`, 301);
    }

    const body = request.method === "HEAD" ? null : wwProtectHtml(renderHero(hero, env));
    return new Response(body, {
      status: 200,
      headers: wwProtectedPageHeaders({
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "public, max-age=300, s-maxage=3600",
        "x-robots-tag": "index, follow, noarchive"
      })
    });
  }
};


